import{_ as t,l as r,o as a,c as s,v as n,p as l,x as o,d,i,S as f}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"fence 的代价","description":"","frontmatter":{"title":"fence 的代价","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fence-cost.md","filePath":"cs/fence-cost.md","lastUpdated":1789023840000}'),p={name:"cs/fence-cost.md"};function h(m,e,_,A,u,E){const c=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=n('<h1 id="fence-的代价" tabindex="-1">fence 的代价 <a class="header-anchor" href="#fence-的代价" aria-label="Permalink to &quot;fence 的代价&quot;">​</a></h1><div class="epigraph"><p>全序栅栏要排空写缓冲、禁止越过它的 load 提前，等于主动关掉乱序与 MLP；正确的程序少用，用错的程序把它当注释重复插。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Intel SDM 对 mfence/sfence/lfence 的描述 整理</footer></div><p><a href="/cs/transactional-memory">上一课</a> 用 abort 代替部分锁。<a href="/cs/acquire-release">acquire/release</a> 已经是单向的。程序员和编译器仍会放出 <code>fence</code> / <code>mfence</code> / <code>dmb</code>。本课不重画写集。缺口是<strong>把栅栏换成流水线里的停顿：SQ drain、load 禁止提前、甚至指令串行化</strong>，并收束本单元。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>弱序核上，没有栅栏则 <a href="/cs/lsq-disambiguation">LSQ</a> 可以让年轻 load 越过年长 store（地址不同时）。设备驱动、无锁、与 GPU 共享的页需要更强顺序。缺口不是新一致性态，而是<strong>fence 在微结构上等于什么，以及它如何毁掉 <a href="/cs/mlp-memory-parallelism">MLP</a> 与 store 缓冲。</strong></p><p><span class="marginnote">x86：<code>sfence</code> 主要排 store；<code>lfence</code> 阻止后续指令在先前 load 前执行；<code>mfence</code> 更强。RISC-V <code>fence rw,rw</code> 的前/后集合可配，不必每次全排空。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：fence 在 ROB 里占一项，直到指定集合里更年长的访存完成一致性动作（store 成为 M 可见、load 数据已返回）。更年轻的同类型访存不得越过。可选：冲刷 <a href="/cs/write-combining">写合并</a>。串行化 fence（如 <code>cpuid</code> 一类）还要等整个 ROB 退休。</p>',8)),(a(),l(f,null,{default:o(()=>[i(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22fence%20%E8%BF%9B%E5%85%A5%20ROB%22%5D%20--%3E%20DRAIN%5B%22%E6%8E%92%E7%A9%BA%E6%8C%87%E5%AE%9A%20SQ%2FLQ%22%5D%0A%20%20DRAIN%20--%3E%20WCB%5B%22%E5%8F%AF%E9%80%89%E5%86%B2%E5%88%B7%20WCB%22%5D%0A%20%20DRAIN%20--%3E%20GO%5B%22%E5%90%8E%E7%BB%AD%E8%AE%BF%E5%AD%98%E6%89%8D%E5%8F%91%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价以「本可以飞行的 miss 被拦住」计，不是 ALU 的一拍。高争用锁若每层都 seq-cst，会把核变成近似顺序机。<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a> 在这里极狠：一小段同步代码的 \\(f\\) 被放大。正确用法是：数据竞争自由的程序把 fence 藏进锁/原子原语，而不是散落在每个共享读。</p><p>本单元收束：替换、预取、VIPT、一致性五态与目录、伪共享、原子、模型、事务、fence。下一单元从并行分类（Flynn）转向向量、SIMT 与互连，不再加宽单核 cache 协议。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 ISA fence 的真值表抄完。也不把 Spectre 的 <code>lfence</code> 串行化当性能优化推荐——那是后课安全与推测，动机相反。Flynn 分类下一课从「单核 ILP」抬到「多指令多数据怎么摆」。</p><p>后课默认：fence 是主动放弃 ILP/MLP 换顺序。并行形态先按 Flynn 分箱，再谈 VLIW 与 GPU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fence 排空指定访存集合，代价是 MLP 与写缓冲。</li><li>能用 acquire/release 就不要用全序。</li><li>下一课序从 Flynn 分类开始谈并行形态。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Intel SDM；RISC-V 内存模型。</li></ul>',8))])}const S=t(p,[["render",h]]);export{B as __pageData,S as default};
